style.css:
@-moz-document domain("youtube.com") {
body {
    background-image: url("https://br.pinterest.com/search/pins/?q=bfdi%20wallpaper%20pc&rs=typed");
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    background-repeat: no-repeat;
  }

  #page-manager, ytd-app {
    background: transparent !important;
  }

  ytd-watch-flexy, ytd-masthead, ytd-mini-guide-renderer, ytd-guide-renderer {
    background-color: rgba(0, 0, 0, 0.6) !important;
    backdrop-filter: blur(5px);
  }

  /* Opcional: esconder fundo branco de alguns elementos */
  #content, #container {
    background: transparent !important;
  }
}
